from pathlib import Path
import json
root=Path('literature-reading/Regulating-Conglomerates');slides=[]
def add(title,section,body,reader,source='',kind=''):
 slides.append(dict(title=title,section=section,body=body,reader=reader,source=source,kind=kind))
def p(s):return '<p>'+s+'</p>'
def ul(*items):return '<ul>'+''.join('<li>'+i+'</li>' for i in items)+'</ul>'
def eq(s):return '<div class="equation">'+s+'</div>'
def note(s):return '<p class="boundary">'+s+'</p>'
def cols(a,b):return '<div class="columns"><div>'+a+'</div><div>'+b+'</div></div>'
def table(head,rows):return '<table><thead><tr>'+''.join('<th>'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table>'
def evidence(name,caption,body,full=None):
 return '<div class="evidence"><figure><button class="image-button" data-image="assets/'+(full or name)+'.png" aria-label="放大查看原文图表"><img src="assets/'+name+'.png" alt="'+caption+'"></button><figcaption>'+caption+' · 点击查看完整大图</figcaption></figure><div class="interpretation">'+body+'</div></div>'
add('监管企业集团','文献汇报', '<div class="cover"><p class="cover-en">Regulating Conglomerates</p><p class="cover-sub">来自中国节能项目的证据</p><div class="cover-rule"></div><p class="cover-authors">Qiaoyi Chen · Zhao Chen · Zhikuo Liu<br>Juan Carlos Suárez Serrato · Daniel Yi Xu</p><p class="journal">American Economic Review · 2025 · 115(2): 408–447</p><p class="presenter">汇报人：<span class="presenter-name">Zhihan</span></p></div>',[1], 'Chen et al. (2025) · DOI: 10.1257/aer.20211455','cover-slide')
add('企业节能能否转化为行业节能？','01 研究问题',p('节能约束施加于名单内企业，生产决策可能由整个集团统筹。')+cols('<h2>监管边界</h2>'+p('单个法人企业的能源消耗受到约束。')+'<div class="statement">受监管企业缩减生产</div>','<h2>决策边界</h2>'+p('集团可在关联企业之间重新安排生产。')+'<div class="statement">未直接受监管的关联企业扩张</div>')+note('研究对象：企业内部调整、集团内生产转移，以及行业市场溢出的共同作用。'),[2,3])
add('实证识别企业反应，模型加总行业影响','01 研究问题', '<div class="sequence"><div><span>01</span><h2>企业层面的证据</h2><p>DID 与事件研究<br>能耗、产出、能源效率</p></div><div><span>02</span><h2>集团与行业机制</h2><p>集团内重新配置<br>市场需求与价格调整</p></div><div><span>03</span><h2>政策与福利评价</h2><p>行业净节能与经济成本<br>替代监管方案</p></div></div>'+note('核心贡献：把所有权网络纳入环境监管的效果评价与政策设计。'),[2,48])
add('千家企业节能行动覆盖高耗能企业','02 制度与数据', '<div class="numbers"><div><strong>1,008</strong><span>纳入名单的企业</span></div><div><strong>18 万吨</strong><span>2004 年年综合能耗门槛<br>单位：吨标准煤</span></div><div><strong>47%</strong><span>名单企业占全国工业能耗比重</span></div></div>'+p('政策于 2006 年公布，覆盖九个高耗能行业，通过目标责任、考核与能源管理推动节能。')+'<div class="timeline"><div><b>2004</b><span>历史能耗确定名单</span></div><div><b>2006</b><span>政策公布／事件研究基年</span></div><div><b>2007 起</b><span>DID 的政策后时期</span></div><div><b>2011 年末</b><span>万家企业行动公布</span></div></div>'+note('受监管表示纳入千家企业能耗管理范围；企业仍可生产。'),[4,5,8])
add('数据连接能源、生产与所有权网络','02 制度与数据',table(['数据','分析用途'],[['CESD 企业能源数据','能耗与能源效率；识别后续纳入万家企业行动的对照企业'],['ASIF 工业企业数据','产值、企业特征与生产变化'],['CARD 股权关联数据','识别集团及关联企业'],['2004 年经济普查','企业分布与结构模型数据矩']])+p('股权联系以至少 25% 的持股、最多两层关系识别；排除仅因共同国资委持股形成的联系。')+note('基准溢出分析进一步限定同一四位行业，以识别生产可替代性较强的关联企业。'),[9,10])
add('能耗衡量总量，能效衡量单位能源的产出','02 制度与数据',table(['指标','含义','示例：政策前 → 政策后'],[['能耗 E','生产使用的能源总量','50 → 40 吨标准煤（−20%）'],['产出 Y','实证主要以产值度量','100 → 80 万元（−20%）'],['能源效率 Y/E','每单位能源对应的产值','2 → 2 万元／吨标准煤（不变）']])+eq('能源强度 = E / Y　；　能源效率 = Y / E')+note('示例仅用于定义。产量收缩可以带来节能；产值口径能效还会受到价格和产品结构影响。'),[6,17])
add('DID 比较两组企业在政策前后的变化','03 识别策略',cols('<h2>受监管企业的直接反应</h2>'+ul('处理组：千家企业名单内企业。','对照组：后续纳入万家企业行动的企业，剔除相关关联企业。','政策后：2007 年及以后。'),'<h2>关联企业的溢出反应</h2>'+ul('处理组：未直接受监管、同一四位行业的关联企业。','对照组：同一四位行业、政策前产出轨迹相近的匹配企业。','能耗结果使用具有能源记录的单独匹配样本。'))+eq('DID =（处理组政策后 − 政策前）−（对照组政策后 − 政策前）')+note('识别依赖：无政策时两组的变化趋势可比。结果反映相对于对照组的变化。'),[11,12,18])
add('固定效应控制企业差异与共同冲击','03 识别策略',eq('z<sub>ijkt</sub> = β (Treat<sub>i</sub> × Post<sub>t</sub>) + α<sub>i</sub> + γ<sub>jt</sub> + δ<sub>kt</sub> + X′<sub>it</sub>θ + ε<sub>ijkt</sub>')+table(['组成','经济含义'],[['z；Treat × Post','z 分别取 ln E、ln Y、ln(Y/E)；交互项仅在处理组且政策后为 1'],['αᵢ：企业固定效应','吸收企业不随时间变化的差异，如长期区位和固有特征'],['γⱼₜ；δₖₜ','吸收二位行业×年份、省份×年份的共同冲击'],['X；β','X 含国有属性、资产收益率、年龄、出口等；β 为相对政策效应']])+note('Table 1 第 (4) 列为完整规格；前几列逐步加入固定效应与企业控制变量。'),[13])
add('企业聚类允许同一企业的误差跨年相关','03 识别策略',cols('<h2>Table 1／Table 2</h2>'+p('同一企业的管理、设备或需求冲击可能持续多年，年度观测并非相互独立。')+eq('cluster(firmid)'),'<h2>估计含义</h2>'+ul('允许同一企业内部各年的残差任意相关。','不同企业簇之间要求近似独立。','相同样本与方程下，聚类方式改变标准误、置信区间和 p 值，系数保持不变。'))+note('固定效应控制条件均值中的共同成分；聚类标准误处理剩余误差的相关性。它本身不修复识别偏误。'),[13,18], 'Table 1–2 表注；Do/Table1.do；Do/Table2.do；Stata vce 文档')
add('行业聚类覆盖同行业企业的共同误差','03 识别策略',table(['做法','允许相关的观测','本论文的应用'],[['按企业聚类','同一家企业的不同年份','名单处理与匹配关联企业 DID'],['按二位行业聚类','同行业不同企业、不同年份','行业监管暴露的市场溢出回归']])+p('行业溢出的处理强度在行业层面变化。同行业企业共同面对需求、价格等冲击，仅按企业聚类可能遗漏跨企业相关性。')+eq('行业溢出：cluster(ind2)')+note('两者用于不同回归，均为单维聚类；标准误大小由误差相关结构决定。行业簇较少时，常规聚类推断仍需谨慎。'),[13,21])
add('事件研究检验政策前趋势并描绘动态反应','03 识别策略',evidence('figure3','Figure 3，Panels A–B',eq('z<sub>it</sub> = Σ<sub>s ≠ 2006</sub> β<sub>s</sub> Treat<sub>i</sub>1(t=s)<br>+ 固定效应 + ε<sub>it</sub>')+ul('2006 年为省略的参照年。','政策前系数用于考察相对趋势；政策后系数反映动态变化。','Panel B 为规范化展示路径。')+note('政策前未发现显著差异，为平行趋势提供支持；不能据此确认所有混杂因素均已排除。')),[14])
add('受监管企业的能耗与产出同时下降','04 实证结果',evidence('table1-ab','Table 1，Panels A–B；四列从左至右排列','<p class="result-label">第 (4) 列</p><h2>能耗：β = −0.128</h2>'+p('标准误 0.048；p = 0.008。<br>精确换算约 −12.0%。')+'<h2>产出：β = −0.145</h2>'+p('标准误 0.042；p = 0.001。<br>精确换算约 −13.5%。')+note('论文用 100β 近似为 −12.8% 与 −14.5%。括号为聚类标准误，方括号为 p 值。'),'table1'),[15,16], '原文 Table 1 · PDF 第 15 页（印刷页 14）')
add('未发现显著的额外能源效率改善','04 实证结果',evidence('table1-c','Table 1，Panel C 及规格控制项','<p class="result-label">第 (4) 列</p><h2>β = −0.019</h2>'+p('标准误 0.047；p = 0.691。<br>估计值与零效应在统计上相容。')+ul('“额外”指相对于对照组的变化。','能耗和产出同步收缩，与缩减生产的机制一致。')+note('该结果仅表明未发现额外能效改善；长期设备更新不在基准分析范围内。'),'table1'),[17], '原文 Table 1 · 能效为产值／能源消耗')
add('同一细分行业的关联企业相对扩张','04 实证结果',evidence('table2-ab','Table 2，Panels A–B','<p class="result-label">Panel A · 第 (4) 列</p><h2>产出：β = +0.127</h2>'+p('标准误 0.035；p < 0.001。<br>近似 +12.7%；精确换算约 +13.5%。')+'<h2>Panel B：安慰剂检验</h2>'+p('同二位、不同四位行业的关联企业：β = −0.003，p = 0.938。')+note('扩张集中在产品替代性较强的关联企业，与集团内转移生产的机制一致。'),'table2'),[18,19], '原文 Table 2 · PDF 第 19 页（印刷页 18）')
add('关联企业增耗，能效变化未显著','04 实证结果',evidence('table2-cd','Table 2，Panels C–D 及规格控制项','<p class="result-label">第 (4) 列</p><h2>能耗：β = +0.318</h2>'+p('标准误 0.094；p = 0.001。<br>近似 +31.8%；精确换算约 +37.4%。')+'<h2>能效：β = −0.087</h2>'+p('标准误 0.099；p = 0.380。<br>未发现显著的相对能效变化。')+note('产出与能耗使用不同样本；能效效应由相应回归单独估计。'),'table2'),[18], '原文 Table 2 · 百分比精确换算：100 × (eᵝ − 1)')
add('关联企业承接约四成产出损失','04 实证结果', '<div class="calculation"><span>2.45</span><b>×</b><span>0.193</span><b>×</b><span>0.127</span><b>÷</b><span>0.145</span><b>≈</b><strong>41%</strong></div>'+table(['数量','含义'],[['2.45','每家受监管企业平均对应的关联企业数量'],['0.193','关联企业相对受监管企业的平均规模'],['0.127／0.145','关联企业产出增长／受监管企业产出降幅（论文近似口径）']])+note('该比例衡量产出损失的承接程度。能源节约的净变化还取决于各企业能耗及行业反应。'),[20], '原文 Section III，脚注 13；Table 1–2')
add('无股权关联的企业也受到市场溢出影响','04 实证结果',evidence('table3-a','Table 3，Panel A','<p class="result-label">第 (2) 列 · 全样本</p><h2>β = +0.073</h2>'+p('标准误 0.019；p = 0.001。<br>平均监管暴露对应约 7.3% 的产值扩张。')+ul('排除直接受监管企业及相关关联企业。','行业节能目标／2004 年行业能耗，按平均暴露标准化。')+note('监管导致的供给收缩可能提高价格和竞争者需求；产值包含价格与数量反应。'),'table3'),[21], '原文 Table 3 · PDF 第 23 页（印刷页 22）')
add('行业暴露 DID 利用行业间监管强度差异','03 识别策略 · 补充',eq('ln Y<sub>ijt</sub> = β (Spillover<sub>j</sub> × Post<sub>t</sub>) + α<sub>i</sub> + τ<sub>t</sub> + Z′<sub>jt</sub>θ + X′<sub>it</sub>γ + ε<sub>ijt</sub>')+table(['设定','作用'],[['连续处理强度 Spilloverⱼ','比较监管暴露较高与较低行业在政策前后的产值变化'],['企业与年份固定效应','控制企业不变特征及所有企业的年度共同冲击'],['行业与企业控制变量','行业产出、行业能耗；部分规格加入企业特征'],['二位行业聚类','允许同行业企业和不同年份的误差相关']])+note('完整的行业×年固定效应会吸收 Spillover×Post，因此本式采用企业与年份固定效应。'),[21])
add('集团内比较识别生产份额的相对转移','04 实证结果',evidence('table3-b','Table 3，Panel B','<p class="result-label">第 (4) 列</p><h2>β = −0.315</h2>'+p('受监管企业相对于同集团关联企业的产出变化；标准误 0.067，p < 0.001。')+ul('集团×年固定效应控制同集团同年的共同冲击。','按集团聚类，允许同集团跨企业、跨年的误差相关。')+note('此处比较基准是同集团关联企业，因此系数与 Table 1 的比较对象不同。'),'table3'),[38], '原文 Table 3 Panel B；Do/Table3.do 第 47–60 行')
add('DID 相对效应需要与行业总效应衔接','05 结构模型',cols('<h2>实证已经揭示</h2>'+ul('受监管企业收缩。','同集团关联企业扩张。','无关企业也出现市场溢出。'),'<h2>加总仍需回答</h2>'+ul('各类企业的能源权重是多少？','价格变化如何改变生产与需求？','节能收益是否覆盖经济成本？'))+eq('相对变化 = 处理组总影响 − 对照组总影响')+note('对照组也可能受市场溢出影响。结构模型提供共同的无政策基准及行业加总。'),[22,23])
add('模型把企业集团作为生产配置的决策主体','05 结构模型',cols('<h2>需求</h2>'+p('不同集团生产差异化产品，CES 替代弹性 σ = 4；同集团企业生产可相互替代的产品。')+eq('Q<sub>j</sub> = Σ<sub>i</sub> q<sub>ij</sub>'),'<h2>供给</h2>'+p('集团共同选择各企业的投入和产量。企业效率沿集团内排序递减，生产具有规模报酬递减。')+eq('q<sub>i</sub> = φ δ<sup>i−1</sup> k<sub>i</sub><sup>αₖ</sup> [min(l<sub>i</sub>, η<sub>i</sub>e<sub>i</sub>)]<sup>αₗ</sup>'))+note('q 为物理产量，φ 为技术效率；实证 Y 主要为产值。基准 η = 1，劳动与能源配比固定。'),[24,25,26,27])
add('效率差异与报酬递减共同决定集团内规模','05 结构模型',eq('q<sub>i</sub> / q<sub>1</sub> = δ<sup>(i−1)/(1−α)</sup>')+cols('<h2>效率随排序下降</h2>'+p('δ ≈ 0.90：第二家企业的效率为核心企业的约 90%。')+'<h2>产量分布更陡峭</h2>'+p('α = 0.90 时，第二家相对产量约 0.35，第三家约 0.12。'),'<h2>生产分散的原因</h2>'+p('把全部投入集中在一家企业会面临更强的边际报酬递减；新增企业又需要固定经营成本。')+p('集团权衡效率、边际收益和固定成本，决定企业数量与投入配置。'))+note('政策后短期分析固定资本和企业数量，重点刻画既有企业之间的投入调整。'),[28,29,30])
add('核心企业配额提高集团内生产转移的收益','05 结构模型',eq('e<sub>1</sub> ≤ ξ e<sub>1</sub><sup>*</sup>　，　ξ = 0.8')+p('核心企业能源投入上限为无政策水平的 80%。配额约束提高其有效边际成本，集团转而增加关联企业投入。')+eq('l<sub>i</sub> / l<sub>1</sub> = δ<sup>(i−1)/(1−α)</sup> × [1 + λ/(w+p<sub>e</sub>)]<sup>1/(1−αₗ)</sup>')+cols('<h2>λ：配额的影子成本</h2>'+p('表示额外放宽一单位能源约束的边际价值。'),'<h2>Λ：有效成本倍数</h2>'+p('Λ = 1 + λ/(w+pₑ)。约束越紧，集团内转移生产的激励越强。'))+note('原文 α = 0.90、αₗ = 0.80；两处指数分别对应不同的边际调整。'),[31,32])
add('价格反馈把企业调整连接为行业均衡','05 结构模型', '<div class="sequence"><div><span>01</span><h2>给定价格</h2><p>求配额影子成本<br>确定集团内投入配置</p></div><div><span>02</span><h2>重新加总</h2><p>计算各集团产量<br>更新行业价格指数</p></div><div><span>03</span><h2>迭代至收敛</h2><p>价格与生产相容<br>按能源权重计算净节能</p></div></div>'+eq('企业约束 → 集团内配置 → 行业供给与价格 → 企业需求')+note('模型固定行业支出等外部条件，刻画相关行业均衡。'),[33])
add('参数分别来自外部校准、数据矩与政策设定','05 结构模型',evidence('table4','Table 4，原表与表注','<h2>外部校准</h2>'+p('σ = 4；α = 0.90；αₗ = 0.80。')+'<h2>矩估计</h2>'+p('δ = 0.900；σₘ = 1.239；<br>存活门槛 φ₁ = 0.609。')+'<h2>政策参数</h2>'+p('覆盖门槛匹配能源份额；<br>1−ξ = 0.20 为配额压降幅度。')),[34], '原文 Table 4 · PDF 第 32 页（印刷页 31）')
add('九个政策前数据矩约束企业与集团分布','05 结构模型',eq('θ̂ = arg min<sub>θ</sub> [m<sub>数据</sub> − m<sub>模型</sub>(θ)]′ W [m<sub>数据</sub> − m<sub>模型</sub>(θ)]')+table(['数据矩','数量','识别信息'],[['三个销售规模区间的企业数量占比','3','企业规模分布'],['相同区间的销售额占比','3','大企业的经济权重'],['第二、第三家相对核心企业的规模','2','集团内效率衰减'],['销售额低于 100 万元的企业占比','1','小企业比例与存活门槛']])+note('给定复现脚本使用单位权重矩阵；Main_test.m 读取已估参数并重算数据矩，未重新优化参数。'),[35])
add('模型预测与企业层面的政策反应相比较','05 结构模型',evidence('figure6','Figure 6，Panel B（论文报告）','<h2>样本外验证</h2>'+p('主要技术参数由政策前分布估计，再与政策后的产出、能耗及能效回归结果比较。')+ul('检验模型能否同时解释多类企业的反应。','多个结果共同约束生产转移与市场反馈机制。')+note('图为论文原图。所给代码中投入分解的变量引用尚待核对，相关能耗／能效预测未确认为本地复现结果。')),[36,51])
add('收入变化由配置、集团规模与市场项共同构成','06 加总与福利',evidence('table5','Table 5，模型分解原表','<h2>分配效应</h2>'+p('企业在集团总产量中的份额发生变化。')+'<h2>集团规模项</h2>'+p('集团总产量变化改变剩余收入。')+'<h2>市场项</h2>'+p('行业价格调整共同影响各集团。')+note('表中是模型对数变化。总效应按三项相加，DID 再扣除对照企业总效应。')),[37,38], '原文 Table 5 · PDF 第 35 页（印刷页 34）')
add('市场溢出改变 DID 与总效应的对应关系','06 加总与福利',table(['企业类型','相对无政策的总效应','扣除对照企业后的 DID'],[['受监管企业','−14.0','−14.0 − 6.5 = −20.5'],['关联企业','+19.3','+19.3 − 6.5 = +12.8'],['对照企业','+6.5','也受到行业市场溢出影响']])+eq('集团内差异：−14.0 − 19.3 = −33.3')+note('数值来自 Table 5，单位为对数变化 × 100。集团内比较消去共同集团规模项与市场项。'),[38])
add('相关行业的净节能约为 4%','06 加总与福利','<div class="numbers"><div><strong>−5.8%</strong><span>受监管集团的能耗变化<br>基期能源权重约 86%</span></div><div><strong>+6.5%</strong><span>其他集团的能耗变化<br>基期能源权重约 14%</span></div><div><strong>≈ −4%</strong><span>加总后的行业能耗变化</span></div></div>'+p('集团内生产转移与行业市场扩张抵消了一部分直接节能，行业仍有净节能。')+eq('本地模型核验：−ln(E / E*) = 3.9644%')+note('覆盖范围为模型中的相关行业；论文换算约每年 4,800 万吨标准煤，与全国累计政策目标口径不同。'),[39,51])
add('福利评价同时计入节能收益与价格成本','06 加总与福利',eq('Δln W / (1−κ) = −ln(P / P*) − [κ/(1−κ)] ln(E / E*)')+cols('<h2>经济成本</h2>'+p('能源约束提高生产成本，行业价格指数上升，降低真实消费。')+'<div class="statement">价格对数变化约 +3.49%</div>','<h2>环境收益</h2>'+p('能源使用减少带来环境收益；κ 表示环境收益在福利中的权重。')+'<div class="statement">能耗对数变化约 −3.96%</div>')+note('环境收益权重达到阈值时，节能收益能够抵消价格上升的成本。'),[40,41,51])
add('福利收支平衡要求减排收益约 161 美元／吨','06 加总与福利','<div class="hero-number">161<span>美元／吨 CO₂</span></div>'+p('GWTP：使政策福利效应恰好为零时，对每吨减排收益的要求。')+eq('κ ≈ 0.467　→　GWTP = κ × GDP × 0.8 / CO₂')+table(['基准换算','含义'],[['2006 年 GDP：2.752 万亿美元；CO₂：63.8 亿吨','将福利中的环境权重转换为每吨金额'],['本地计算：161.45 美元／吨 CO₂','与论文报告约 161 美元一致']])+note('该值是模型给出的收益门槛。114–199 美元为不同模型设定下的敏感性范围。'),[42,43])
add('集团监管改善生产配置与节能的权衡','07 政策比较',evidence('figure7','Figure 7，Panel B','<h2>企业监管</h2>'+p('约束单个企业，可能引起集团内向低效率企业转移生产。')+'<h2>集团监管</h2>'+p('约束集团总能耗，保留集团内部选择生产地点的空间。')+note('在相同价格成本下，论文比较中净节能约由 3.97% 升至 4.36%，提高约 10%。')),[44,45])
add('改进监管单位与扩大覆盖范围对应不同机制','07 政策比较',table(['方案','调整维度','论文模型中的比较'],[['扩大企业名单','监管覆盖范围','覆盖更多企业，但仍需考虑集团内配置'],['集团监管','监管与决策的边界','减少集团内生产转移造成的配置损失'],['统一能源税','统一边际能源成本','作为政策效率的比较基准']])+p('基准福利门槛约为 161 美元／吨 CO₂；集团监管约 154 美元，统一税约 153 美元。')+note('相同配额参数的比较与相同价格成本的比较具有不同口径；上述结果依赖模型设定。'),[45])
add('监管效果取决于企业网络与市场调整','08 结论','<div class="conclusions"><div><span>01</span><p><b>直接节能伴随生产收缩。</b><br>受监管企业能耗与产出下降，未发现显著的额外能效改善。</p></div><div><span>02</span><p><b>生产反应超出名单边界。</b><br>关联企业承接生产，无关企业也通过市场溢出扩张。</p></div><div><span>03</span><p><b>监管单位影响政策效率。</b><br>集团监管为内部配置保留空间，改善模型中的成本与节能权衡。</p></div></div>'+note('适用范围：历史政策、同一细分行业关联企业及短期行业均衡；结果不能直接外推至全部产业和长期技术变迁。'),[48,49])
add('复现将原始回归与结构模型分开核验','技术附录',table(['模块','文件路径','产出'],[['微观回归','Data_Generation_Program → Do/Table1–3.do','清理／匹配样本，估计 DID 与事件研究'],['参数与数据矩','Structural_Analysis/Estimation','读取参数，求模型矩与数据矩距离'],['政策均衡','Counterfactual Baseline/Main.m','价格、能耗、收入分解'],['政策比较','Main_compare.m → Do/Figure7.do','18 组覆盖门槛×配额组合及替代方案']])+note('本演示稿保留 24 处原文件代码摘录与中文解释。各页“对应代码”连接相关计算；完整讲义保留全部细节。'),[50])
add('本地核验确认基准均衡，微观回归未重跑','技术附录',table(['核验项目','结果／状态'],[['模型价格比／能耗比','1.03547156 ／ 0.96113137'],['GWTP','161.45 美元／吨 CO₂'],['参数与微观回归','使用已估参数；所给副本不含 .dta，未重估微观回归'],['政策覆盖门槛','本地约 9.344；论文出表脚本为 9.289'],['投入分解变量引用','share_input_* 与加权计算使用变量有差异，相关预测待核对']])+note('运行环境：MATLAB R2024a；2026-10-11；Main_test.m、Main.m 与 Main_compare.m。'),[51])
